package org.deeptimeline.app
fun main(){fun event(id:String,sec:Long,threshold:String="",unit:String="DAY")=TimelineEvent(id=id,title=id,moment=Moment(sec,0),civil="1970-01-01T00:00",mode="UTC",coords="",zone="UTC",offsetNano="0",maxScaleAmount=threshold,maxScaleUnit=unit)
val origin=event("origin",0,"1/3");val near=event("near",86400);val far=event("far",86400*1000);check(SearchNavigation.spanFor(origin,listOf(origin,near,far),86400.0*365)<86400.0/3.0);check(SearchNavigation.spanFor(origin,listOf(origin,near,far),1800.0)==1800.0);check(SearchNavigation.spanFor(far,listOf(origin,near,far),1e12)==86400.0*999*6);check(SearchNavigation.spanFor(origin.copy(maxScaleAmount="1/7"),listOf(origin,far),1e10)<86400.0/7.0);check(SearchNavigation.spanFor(origin.copy(maxScaleAmount=""),listOf(origin),1e10)==1e10);check(SearchNavigation.spanFor(event("tiny",0,"1e-9"),listOf(),1e6)==0.0000432);println("Search snap-and-zoom, nearest-neighbor context and hidden-event reveal: PASS")}
